# Manacher：插入分隔符，统一奇偶回文，均摊 O(n)
class Solution:
    def longestPalindrome(self, s: str) -> str:
        t = "#" + "#".join(s) + "#"
        n = len(t)
        p = [0] * n
        c = r = 0
        best_len = best_c = 0
        for i in range(n):
            if i < r:
                p[i] = min(r - i, p[2 * c - i])
            while (i - p[i] - 1 >= 0 and i + p[i] + 1 < n
                   and t[i - p[i] - 1] == t[i + p[i] + 1]):
                p[i] += 1
            if i + p[i] > r:
                c, r = i, i + p[i]
            if p[i] > best_len:
                best_len, best_c = p[i], i
        start = (best_c - best_len) // 2
        return s[start:start + best_len]

def quick_sort_hoare(nums):
    """另一种写得出彩的版本：Hoare 划分 + 三数取中。面试里说清楚「为什么比 Lomuto 少交换」。"""
    def median3(lo, hi):
        mid = (lo + hi) // 2
        a, b, c = nums[lo], nums[mid], nums[hi]
        if a > b:
            lo, mid = mid, lo
        if nums[lo] > nums[hi]:
            lo, hi = hi, lo
        if nums[mid] > nums[hi]:
            mid, hi = hi, mid
        return nums[mid]

    def partition(lo, hi):
        pivot = median3(lo, hi)
        i, j = lo - 1, hi + 1
        while True:
            i += 1
            while nums[i] < pivot:
                i += 1
            j -= 1
            while nums[j] > pivot:
                j -= 1
            if i >= j:
                return j
            nums[i], nums[j] = nums[j], nums[i]

    def sort(lo, hi):
        if lo >= hi:
            return
        p = partition(lo, hi)
        sort(lo, p)
        sort(p + 1, hi)

    sort(0, len(nums) - 1)
    return nums

