class DSU:
    """路径压缩 + 按秩（大小）合并，近似 O(alpha(n))。"""
    def __init__(self, n):
        self.p = list(range(n))
        self.rank = [0] * n
        self.count = n                      # 连通分量个数

    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]    # 路径减半
            x = self.p[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1
        return True


def num_islands(grid):
    """岛屿数量（lc200）用并查集实现：把每个 '1' 与左/上邻居 union。"""
    if not grid or not grid[0]:
        return 0
    R, C = len(grid), len(grid[0])
    dsu = DSU(R * C)
    ones = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] != "1":
                continue
            ones += 1
            for dr, dc in ((0, -1), (-1, 0)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "1":
                    dsu.union(r * C + c, nr * C + nc)
    # 连通分量数 = 并查集中仍以 '1' 为根的集合数
    roots = {dsu.find(r * C + c) for r in range(R) for c in range(C) if grid[r][c] == "1"}
    return len(roots)

