class Solution:
    def permute(self, nums):
        res, path = [], []
        used = [False] * len(nums)

        def backtrack():
            if len(path) == len(nums):
                res.append(path[:])        # 深拷贝
                return
            for i in range(len(nums)):
                if used[i]:
                    continue
                used[i] = True
                path.append(nums[i])
                backtrack()
                path.pop()                 # 撤销
                used[i] = False

        backtrack()
        return res

