def length_of_lis(nums):
    """O(n log n)：tails[k] 记录「长度 k+1 的上升子序列的最小结尾」。"""
    import bisect

    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)     # 第一个 >= x 的位置
        if i == len(tails):
            tails.append(x)                  # x 比所有结尾都大 → 子序列变长
        else:
            tails[i] = x                     # 否则把该长度的结尾改小（更优）
    return len(tails)

