def length_of_lis_dp(nums):
    """O(n^2) 定义解：dp[i] = 以 nums[i] 结尾的 LIS 长度。先说这个再优化，面试节奏更稳。"""
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def merge_two_lists_rec(l1, l2):
    """递归版：代码短，但递归深度 = 链表长度，长链表有爆栈风险，面试要主动说出来。"""
    if not l1:
