def level_order_dfs(root):
    """DFS + 深度下标：把「层」当成一次先序遍历的副作用，面试里作为第二种写法很加分。"""
    out = []

    def dfs(node, d):
        if not node:
            return
        if d == len(out):
            out.append([])
        out[d].append(node.val)
        dfs(node.left, d + 1)
        dfs(node.right, d + 1)

    dfs(root, 0)
    return out

