def is_valid(s):
    """栈 + 字典映射。闭括号来了必须和栈顶配对，否则直接 False。"""
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in pairs:
            # 栈空（多了一个闭括号）或栈顶不匹配 → 非法
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack              # 全部配对完栈必须为空

