def merge_sorted_array_front(nums1, m, nums2, n):
    """从前向后 + 临时副本：需要 O(m) 额外空间，用它反衬「从后往前」为什么更优。"""
    a = nums1[:m]
    i = j = 0
    for k in range(m + n):
