def decodeString(s):
    stack = []          # 每层: [外层已解码串, 重复次数]
    num = 0
    cur = ""
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)     # 处理多位数字
        elif ch == '[':
            stack.append([cur, num])     # 寄存外层
            cur, num = "", 0             # 开启内层
        elif ch == ']':
            prev, k = stack.pop()
            cur = prev + cur * k         # 拼回外层
        else:
            cur += ch                    # 普通字母
    return cur


