class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        idx = {v: i for i, v in enumerate(inorder)}

        def build(in_lo, in_hi, post_lo, post_hi):
            if in_lo > in_hi:
                return None
            root = TreeNode(postorder[post_hi])
            mid = idx[root.val]
            left = mid - in_lo
            root.left = build(in_lo, mid - 1, post_lo, post_lo + left - 1)
            root.right = build(mid + 1, in_hi, post_lo + left, post_hi - 1)
            return root

        return build(0, len(inorder) - 1, 0, len(postorder) - 1)


