def restore_ip_addresses_iter(s):
    """三重循环暴力定切点：O(1) 段数所以是常数级枚举，胜在没有递归、边界一眼看清。"""
    n = len(s)
    out = []
    for a in range(1, 4):
        for b in range(1, 4):
            for c in range(1, 4):
                d = n - a - b - c
                if d < 1 or d > 3:
                    continue
                parts = [s[:a], s[a:a + b], s[a + b:a + b + c], s[a + b + c:]]
                if any(p[0] == "0" and len(p) > 1 for p in parts):
                    continue
                if all(0 <= int(p) <= 255 for p in parts):
                    out.append(".".join(parts))
    return out

