import sys


def bellman_ford_negative_cycle(n, edges, start, end):
    """返回 'circle' / 'unconnected' 或最低成本字符串。"""
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[start] = 0
    negative_cycle = False
    for i in range(1, n + 1):                 # 一共松弛 n 轮
        for u, v, w in edges:
            if dist[u] == INF:
                continue                      # 不可达节点不参与松弛
            if i < n:
                if dist[u] + w < dist[v]:     # 前 n-1 轮：正常松弛
                    dist[v] = dist[u] + w
            else:
                if dist[u] + w < dist[v]:     # 第 n 轮：只检测，不写回
                    negative_cycle = True
    if negative_cycle:
        return "circle"
    if dist[end] == INF:
        return "unconnected"
    return str(dist[end])


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    edges = []
    for _ in range(m):
        s = int(data[idx]); idx += 1
        t = int(data[idx]); idx += 1
        w = int(data[idx]); idx += 1
        edges.append((s, t, w))
    print(bellman_ford_negative_cycle(n, edges, 1, n))


if __name__ == "__main__":
    main()

