from collections import deque


def spfa_negative_cycle(n, edges, start, end):
    """SPFA：某节点入队次数达到 n 次即判定负权回路。"""
    INF = float('inf')
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))
    dist = [INF] * (n + 1)
    dist[start] = 0
    count = [0] * (n + 1)          # 入队次数
    in_queue = [False] * (n + 1)   # 关键：去重，避免同轮反复计数
    count[start] = 1
    dq = deque([start])
    in_queue[start] = True
    has_cycle = False
    while dq:
        u = dq.popleft()
        in_queue[u] = False
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                if not in_queue[v]:
                    dq.append(v)
                    in_queue[v] = True
                    count[v] += 1
                    if count[v] >= n:
                        has_cycle = True
                        break
        if has_cycle:
            break
    if has_cycle:
        return "circle"
    if dist[end] == INF:
        return "unconnected"
    return str(dist[end])

def canFinish(numCourses, prerequisites):
    g = [[] for _ in range(numCourses)]
    for a, b in prerequisites:
        g[b].append(a)
    color = [0] * numCourses   # 0 未访问 1 在栈中 2 已完成
    def dfs(u):
        color[u] = 1
        for v in g[u]:
            if color[v] == 1:
                return False        # 回到栈中的点 => 有环
            if color[v] == 0 and not dfs(v):
                return False
        color[u] = 2
        return True
    return all(color[i] != 0 or dfs(i) for i in range(numCourses))

print(canFinish(2, [[1, 0]]), canFinish(2, [[1, 0], [0, 1]]))

def has_cycle_hash(head):
    """哈希存访问过的结点：O(n) 额外空间，但能顺带回答「环的入口在哪」。"""
    seen = set()
    cur = head
    while cur:
        if id(cur) in seen:
            return True
        seen.add(id(cur))
        cur = cur.next
    return False

