import heapq


def knight_astar(n, start, goal):
    """n 为棋盘边长；start/goal 为 1-indexed 的 (row, col)。
    返回最少步数，不可达返回 -1。"""
    sx, sy = start[0] - 1, start[1] - 1
    gx, gy = goal[0] - 1, goal[1] - 1
    moves = [(1, 2), (2, 1), (-1, 2), (-2, 1),
             (1, -2), (2, -1), (-1, -2), (-2, -1)]

    def h(x, y):
        dx, dy = abs(x - gx), abs(y - gy)
        return max((dx + dy + 2) // 3, (max(dx, dy) + 1) // 2)

    dist = {(sx, sy): 0}
    pq = [(h(sx, sy), 0, sx, sy)]
    while pq:
        f, g, x, y = heapq.heappop(pq)
        if (x, y) == (gx, gy):
            return g
        if g > dist.get((x, y), float('inf')):
            continue
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and g + 1 < dist.get((nx, ny), float('inf')):
                dist[(nx, ny)] = g + 1
                heapq.heappush(pq, (g + 1 + h(nx, ny), g + 1, nx, ny))
    return -1


if __name__ == "__main__":
    print(knight_astar(8, (1, 1), (8, 8)))  # 6

