from collections import deque

class Codec:
    def serialize(self, root) -> str:
        out = []
        def dfs(node):
            if node is None:
                out.append('#')
                return
            out.append(str(node.val))
            dfs(node.left)
            dfs(node.right)
        dfs(root)
        return ','.join(out)

    def deserialize(self, data: str):
        tokens = iter(data.split(','))
        def build():
            tok = next(tokens)
            if tok == '#':
                return None
            node = TreeNode(int(tok))
            node.left = build()
            node.right = build()
            return node
        return build()

