from itertools import zip_longest

def compareVersion(version1: str, version2: str) -> int:
    parts1 = version1.split('.')
    parts2 = version2.split('.')
    for s1, s2 in zip_longest(parts1, parts2, fillvalue='0'):
        n1, n2 = int(s1), int(s2)
        if n1 < n2:
            return -1
        if n1 > n2:
            return 1
    return 0

