def largest_sum_after_k_negations(nums, k):
    """返回恰好执行 k 次取反后数组可能的最大和。"""
    nums.sort(key=abs, reverse=True)      # 按绝对值降序，优先处理大绝对值
    for i in range(len(nums)):
        if nums[i] < 0 and k > 0:
            nums[i] = -nums[i]
            k -= 1
    if k % 2 == 1:                        # 剩余奇数次：翻绝对值最小的
        nums[-1] = -nums[-1]
    return sum(nums)


if __name__ == "__main__":
    print(largest_sum_after_k_negations([4, 2, 3], 1))        # 5
    print(largest_sum_after_k_negations([3, -1, 0, 2], 3))    # 6
    print(largest_sum_after_k_negations([2, -3, -1, 5, -4], 2))  # 13

