import heapq


def largest_sum_heap(nums, k):
    """k 很小、n 很大时：用小顶堆每次翻当前最小值。"""
    heapq.heapify(nums)
    for _ in range(k):
        x = heapq.heappop(nums)
        heapq.heappush(nums, -x)
    return sum(nums)

