def all_pairs_shortest(n, roads):
    """n 个点（1..n），roads: [[u, v, w], ...] 双向边。
    返回 (n+1)x(n+1) 的距离矩阵，下标 0 不用。"""
    INF = float('inf')
    d = [[INF] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        d[i][i] = 0
    for u, v, w in roads:
        if w < d[u][v]:
            d[u][v] = w
            d[v][u] = w          # 双向边
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            if d[i][k] == INF:
                continue
            dik = d[i][k]
            for j in range(1, n + 1):
                if dik + d[k][j] < d[i][j]:
                    d[i][j] = dik + d[k][j]
    return d


if __name__ == "__main__":
    d = all_pairs_shortest(4, [[1, 2, 1], [2, 3, 2], [3, 4, 3], [1, 4, 10]])
    print(d[1][4], d[2][4])  # 6 5

