import heapq


def dijkstra_all(n, roads):
    """稀疏、非负权图更快的替代：每个点跑一次 Dijkstra。"""
    adj = [[] for _ in range(n + 1)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]
    for s in range(1, n + 1):
        dist[s][s] = 0
        pq = [(0, s)]
        while pq:
            du, u = heapq.heappop(pq)
            if du > dist[s][u]:
                continue
            for v, w in adj[u]:
                if du + w < dist[s][v]:
                    dist[s][v] = du + w
                    heapq.heappush(pq, (dist[s][v], v))
    return dist

