class Solution:
    def calculate(self, s: str) -> int:
        st = []
        num = 0
        op = '+'
        for i, ch in enumerate(s + '+'):
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch != ' ':
                if op == '+':
                    st.append(num)
                elif op == '-':
                    st.append(-num)
                elif op == '*':
                    st[-1] *= num
                else:
                    st[-1] = int(st[-1] / num)
                op = ch
                num = 0
        return sum(st)

